/**
 * Create and manage mobile-friendly announcement and notice banners displayed across the site.
 *
 * This interface was referenced by `Config`'s JSON-Schema
 * via the `definition` "banners".
 */
export interface Banner {
  id: string;
  /**
   * Internal title used to identify this notice in the admin panel (e.g. "Scheduled Maintenance Alert").
   */
  title: string;
  /**
   * Toggle this notice on or off. Only active banners are rendered to visitors.
   */
  isActive?: boolean | null;
  /**
   * The main message text displayed on the banner. Keep it concise for optimal mobile display.
   */
  content: string;
  /**
   * Optional small badge pill (e.g. "Notice", "New", "Important", "Offer", "Alert").
   */
  badge?: string | null;
  icon?: ('megaphone' | 'bell' | 'zap' | 'alert' | 'info' | 'check' | 'none') | null;
  /**
   * Select how you want to style the banner background.
   */
  backgroundType?: ('preset' | 'custom' | 'gradient') | null;
  presetTheme?:
    | (
        | 'teal'
        | 'blue'
        | 'amber'
        | 'rose'
        | 'emerald'
        | 'violet'
        | 'dark'
        | 'gradient-sunset'
        | 'gradient-aurora'
        | 'gradient-cyber'
      )
    | null;
  /**
   * Enter any valid CSS color, e.g. #0f766e, #1e293b, or rgb(15, 118, 110).
   */
  customColor?: string | null;
  /**
   * Enter any valid CSS linear-gradient or radial-gradient string.
   */
  customGradient?: string | null;
  textColor?: ('white' | 'dark' | 'custom') | null;
  customTextColor?: string | null;
  /**
   * Allow visitors to dismiss/hide the banner by clicking the small close icon.
   */
  isDismissible?: boolean | null;
  /**
   * How many days until the banner reappears for dismissed users (0 = session only). Note: Updating the banner re-shows it immediately.
   */
  dismissExpiryDays?: number | null;
  link?: {
    enableLink?: boolean | null;
    label?: string | null;
    url?: string | null;
    newTab?: boolean | null;
  };
  /**
   * Higher numbers take priority when multiple banners are active.
   */
  priority?: number | null;
  /**
   * Keeps the banner pinned at the very top as the user scrolls.
   */
  isSticky?: boolean | null;
  /**
   * Optional date when the banner starts displaying.
   */
  startDate?: string | null;
  /**
   * Optional expiration date when the banner automatically hides.
   */
  endDate?: string | null;
  updatedAt: string;
  createdAt: string;
}
